/// A message fetched during background push processing (Tier 2).
class FetchedMessage {
  final String fromPeer;
  final String text;
  final PlatformInt64 timestamp;
  final String messageId;

  /// On-disk path to the message's image, if this DM carried an inlined image
  /// that the fetch node decrypted and wrote. Lets the push notification show
  /// a BigPicture preview. None for text-only messages.
  final String? imagePath;

  /// Set for channel messages (channel wake): owning server.
  final String? serverId;

  /// Set for channel messages (channel wake): owning channel.
  final String? channelId;

  const FetchedMessage({
    required this.fromPeer,
    required this.text,
    required this.timestamp,
    required this.messageId,
    this.imagePath,
    this.serverId,
    this.channelId,
  });

  @override
  int get hashCode =>
      fromPeer.hashCode ^
      text.hashCode ^
      timestamp.hashCode ^
      messageId.hashCode ^
      imagePath.hashCode ^
      serverId.hashCode ^
      channelId.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is FetchedMessage &&
          runtimeType == other.runtimeType &&
          fromPeer == other.fromPeer &&
          text == other.text &&
          timestamp == other.timestamp &&
          messageId == other.messageId &&
          imagePath == other.imagePath &&
          serverId == other.serverId &&
          channelId == other.channelId;
}

