/// FFI-facing public channel entry for guest viewer.
class PublicChannelEntryFfi {
  final String channelId;
  final String name;
  final String? category;

  const PublicChannelEntryFfi({
    required this.channelId,
    required this.name,
    this.category,
  });

  @override
  int get hashCode => channelId.hashCode ^ name.hashCode ^ category.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is PublicChannelEntryFfi &&
          runtimeType == other.runtimeType &&
          channelId == other.channelId &&
          name == other.name &&
          category == other.category;
}

/// Display metadata for a channel push notification (Tier 1-style: resolved
/// from the local DB, no node needed).
class PushChannelMeta {
  final String serverName;
  final String channelName;

  /// Effective LOCAL notification level for this channel ("all" / "mentions"
  /// / "nothing") — channel override falling back to the server default.
  /// Lets the Android background handler drop a push whose relay-side filter
  /// was stale.
  final String notifLevel;

  const PushChannelMeta({
    required this.serverName,
    required this.channelName,
    required this.notifLevel,
  });

  @override
  int get hashCode =>
      serverName.hashCode ^ channelName.hashCode ^ notifLevel.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is PushChannelMeta &&
          runtimeType == other.runtimeType &&
          serverName == other.serverName &&
          channelName == other.channelName &&
          notifLevel == other.notifLevel;
}

/// Profile data for push notifications (Tier 1: cached profile, no node needed).
class PushProfile {
  final String displayName;
  final Uint8List? avatarBytes;

  const PushProfile({required this.displayName, this.avatarBytes});

  @override
  int get hashCode => displayName.hashCode ^ avatarBytes.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is PushProfile &&
          runtimeType == other.runtimeType &&
          displayName == other.displayName &&
          avatarBytes == other.avatarBytes;
}

/// Lightweight FFI mirror of node::types::ShareEntryRef.
class ShareEntry {
  final String rootHash;
  final String fileName;
  final BigInt totalSize;
  final int chunksHave;
  final int chunksTotal;
  final String state;
  final bool seeding;
  final String? diskPath;
  final BigInt bytesUploaded;
  final String shareLink;
  final PlatformInt64 createdAt;
  final String? serverId;
  final String? contextType;

  const ShareEntry({
    required this.rootHash,
    required this.fileName,
    required this.totalSize,
    required this.chunksHave,
    required this.chunksTotal,
    required this.state,
    required this.seeding,
    this.diskPath,
    required this.bytesUploaded,
    required this.shareLink,
    required this.createdAt,
    this.serverId,
    this.contextType,
  });

  @override
  int get hashCode =>
      rootHash.hashCode ^
      fileName.hashCode ^
      totalSize.hashCode ^
      chunksHave.hashCode ^
      chunksTotal.hashCode ^
      state.hashCode ^
      seeding.hashCode ^
      diskPath.hashCode ^
      bytesUploaded.hashCode ^
      shareLink.hashCode ^
      createdAt.hashCode ^
      serverId.hashCode ^
      contextType.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ShareEntry &&
          runtimeType == other.runtimeType &&
          rootHash == other.rootHash &&
          fileName == other.fileName &&
          totalSize == other.totalSize &&
          chunksHave == other.chunksHave &&
          chunksTotal == other.chunksTotal &&
          state == other.state &&
          seeding == other.seeding &&
          diskPath == other.diskPath &&
          bytesUploaded == other.bytesUploaded &&
          shareLink == other.shareLink &&
          createdAt == other.createdAt &&
          serverId == other.serverId &&
          contextType == other.contextType;
}

